<?php $rows=$pdo->query("SELECT l.*,b.full_name borrower,e.name equipment,i.asset_code,DATEDIFF(CURDATE(),l.due_date) days_overdue FROM loans l JOIN borrowers b ON b.id=l.borrower_id JOIN equipment_items i ON i.id=l.item_id JOIN equipment e ON e.id=i.equipment_id WHERE l.returned_at IS NULL AND l.due_date<CURDATE() ORDER BY l.due_date")->fetchAll();layout_start('Overdue loans','overdue'); ?><div class="page-heading"><div><p class="eyebrow">FOLLOW UP</p><h1>Overdue loans</h1><p class="muted">Automatically identified from the due date and return record.</p></div></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Borrower</th><th>Equipment</th><th>Issued</th><th>Due date</th><th>Overdue by</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=h($r['borrower'])?></td><td><?=h($r['equipment'])?><small class="cell-sub"><?=h($r['asset_code'])?></small></td><td><?=date('j M Y',strtotime($r['issued_at']))?></td><td><?=date('j M Y',strtotime($r['due_date']))?></td><td><span class="badge overdue"><?=$r['days_overdue']?> day<?=$r['days_overdue']==1?'':'s'?></span></td><td><a class="button small secondary" href="?page=return&id=<?=$r['id']?>">Process return</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="table-empty">No overdue loans. All due dates are up to date.</div><?php endif; ?></div></section><?php layout_end();
